        direct = ('child', 'descendant_of_child', 'grandchild', 'brother', 'sister', 'stepbrother', 'stepsister', 'father', 'mother', 'ancestor_of_father', 'ancestor_of_mother', 'grandfather', 'grandmother', 'stepfather', 'stepmother', 'son_of_brother', 'daughter_of_brother', 'son_of_sister', 'daughter_of_sister', 'nephew', 'niece', 'brother_of_father', 'sister_of_father', 'brother_of_mother', 'sister_of_mother', 'uncle', 'aunt', 'son_in_law', 'daughter_in_law', 'father_in_law', 'mother_in_law', 'brother_in_law', 'sister_in_law')
